bool squareIsWhite(string coordinates) {
    // build an 8 by 8 board, alternating colors like a real chessboard
    vector<vector<string>> board(8, vector<string>(8));
    for (int r = 0; r < 8; r++) {
        for (int c = 0; c < 8; c++) {
            // r=0, c=0 (the a1 corner) is black on a real board
            board[r][c] = (r + c) % 2 == 0 ? "black" : "white";
        }
    }
    // convert the coordinate string, for example "c7", into board indices
    int col = coordinates[0] - 'a';   // 'a' to 'h' becomes 0 to 7
    int row = coordinates[1] - '1';   // '1' to '8' becomes 0 to 7
    // look the color up in the board we just built
    return board[row][col] == "white";
}

int main() {
    string coordinates = "h3";
    cout << boolalpha << squareIsWhite(coordinates) << endl;
    return 0;
}

