public class Main {
    boolean squareIsWhite(String coordinates) {
        int col = coordinates.charAt(0) - 'a';   // 'a' to 'h' becomes 0 to 7, no grid needed
        int row = coordinates.charAt(1) - '1';   // '1' to '8' becomes 0 to 7
        // an even sum lands on a black square, an odd sum lands on a white square
        return (col + row) % 2 != 0;
    }

    public static void main(String[] args) {
        String coordinates = "h3";
        Main solution = new Main();
        System.out.println(solution.squareIsWhite(coordinates));
    }
}

