import java.util.*;

public class Main {
    boolean squareIsWhite(String coordinates) {
        int col = coordinates.charAt(0) - 'a';
        int row = coordinates.charAt(1) - '1';
        // XOR of the last bits is equivalent to checking (col + row) % 2,
        // a common interview micro-variant, not a complexity improvement
        return ((col ^ row) & 1) == 1;
    }

    public static void main(String[] args) {
        String coordinates = "h3";
        Main solution = new Main();
        System.out.println(solution.squareIsWhite(coordinates));
    }
}

